import React from "react";
import {
  AbsoluteFill,
  useCurrentFrame,
  useVideoConfig,
  spring,
  interpolate,
  Img,
  staticFile,
} from "remotion";
import { TransitionSeries, linearTiming } from "@remotion/transitions";
import {
  cameraDrift,
  hardCut,
} from "../transitions";
import {
  SPRINGS,
  TIMING,
  springIn,
  staggeredSpring,
  ambientDrift,
} from "../motion";
import { BRAND } from "@/lib/brand";

export const fps = 25;

const COLORS = {
  bg: BRAND.colors.bg,
  card: BRAND.colors.card,
  border: BRAND.colors.border,
  text: BRAND.colors.text,
  textMuted: BRAND.colors.textMuted,
  textSubtle: BRAND.colors.textSubtle,
  orange: BRAND.colors.orange,
  orangeDeep: BRAND.colors.orangeDeep,
  orangeTint: BRAND.colors.orangeTint,
};

const TRANSITION = Math.max(1, Math.round(fps / 25));

const MONO = "monospace";
const MARKETING = "'GT Walsheim', Inter, sans-serif";
const BODY = "Inter, sans-serif";

const PROMPT = "find me a list of fresh B2B leads in fintech";
const ANSWER = "Sure — spinning up 4 sub-agents to crawl the web.";

// ---------------------------------------------------------------------------
// Background — painted ONCE at the root.
// ---------------------------------------------------------------------------
const Background: React.FC = () => (
  <AbsoluteFill>
    <Img
      src={staticFile("assets/backgrounds/Corner_Background_Orange.png")}
      style={{ width: "100%", height: "100%", objectFit: "cover" }}
    />
  </AbsoluteFill>
);

// ---------------------------------------------------------------------------
// Shared terminal chrome
// ---------------------------------------------------------------------------
const TerminalChrome: React.FC<{
  progress: number;
  children: React.ReactNode;
  title?: string;
}> = ({ progress, children, title = "claude — code" }) => {
  const frame = useCurrentFrame();
  const driftY = ambientDrift(frame, 3, 120, "term-drift");
  const sc = interpolate(progress, [0, 1], [0.95, 1]);
  const ty = interpolate(progress, [0, 1], [50, 0]);
  const bl = interpolate(progress, [0, 1], [10, 0]);
  return (
    <div
      style={{
        width: "100%",
        height: "100%",
        backgroundColor: COLORS.card,
        border: `1px solid ${COLORS.border}`,
        borderRadius: 28,
        overflow: "hidden",
        boxShadow: "0 40px 100px rgba(0,0,0,0.5)",
        opacity: progress,
        transform: `translateY(${ty + driftY}px) scale(${sc}) perspective(1600px) rotateX(${interpolate(
          progress,
          [0, 1],
          [4, 0],
        )}deg)`,
        filter: `blur(${bl}px)`,
        display: "flex",
        flexDirection: "column",
      }}
    >
      {/* title bar */}
      <div
        style={{
          display: "flex",
          alignItems: "center",
          gap: 16,
          padding: "26px 36px",
          borderBottom: `1px solid ${COLORS.border}`,
        }}
      >
        <div style={{ display: "flex", gap: 12 }}>
          {[COLORS.orange, COLORS.border, COLORS.border].map((c, i) => (
            <div
              key={i}
              style={{
                width: 20,
                height: 20,
                borderRadius: "50%",
                backgroundColor: c,
              }}
            />
          ))}
        </div>
        <div
          style={{
            fontFamily: MONO,
            fontSize: 26,
            color: COLORS.textSubtle,
            letterSpacing: "0.04em",
          }}
        >
          {title}
        </div>
      </div>
      {/* body */}
      <div style={{ flex: 1, padding: "40px 48px", position: "relative" }}>
        {children}
      </div>
    </div>
  );
};

// Blinking cursor block
const Cursor: React.FC<{ frame: number; size?: number }> = ({
  frame,
  size = 34,
}) => {
  const blink = Math.sin(frame / 5) > 0 ? 1 : 0.15;
  return (
    <span
      style={{
        display: "inline-block",
        width: size * 0.6,
        height: size,
        backgroundColor: COLORS.orange,
        marginLeft: 6,
        transform: "translateY(6px)",
        opacity: blink,
      }}
    />
  );
};

// Typewriter helper — returns substring of `text` based on frame window
function typed(text: string, frame: number, start: number, cps: number) {
  const chars = Math.max(0, Math.floor((frame - start) * (cps / fps)));
  return text.slice(0, chars);
}

// Reusable static prompt line (the user's question) — shared across scenes
const PromptLine: React.FC<{
  text: string;
  showCursor?: boolean;
  frame?: number;
}> = ({ text, showCursor = false, frame = 0 }) => (
  <div
    style={{
      display: "flex",
      alignItems: "flex-start",
      gap: 20,
    }}
  >
    <span
      style={{
        fontSize: 40,
        color: COLORS.orange,
        fontWeight: 600,
        fontFamily: MONO,
      }}
    >
      ›
    </span>
    <div
      style={{
        fontSize: 44,
        color: COLORS.text,
        lineHeight: 1.3,
        fontFamily: MONO,
      }}
    >
      {text}
      {showCursor && <Cursor frame={frame} size={40} />}
    </div>
  </div>
);

// Reusable static answer line (Claude's response) — shared across scenes
const AnswerLine: React.FC<{
  text: string;
  showCursor?: boolean;
  frame?: number;
}> = ({ text, showCursor = false, frame = 0 }) => (
  <div
    style={{
      display: "flex",
      alignItems: "flex-start",
      gap: 20,
      fontFamily: MONO,
      marginTop: 4,
    }}
  >
    <span
      style={{
        fontSize: 34,
        color: COLORS.orange,
        fontWeight: 600,
      }}
    >
      ✦
    </span>
    <div
      style={{
        fontSize: 40,
        color: COLORS.text,
        lineHeight: 1.3,
      }}
    >
      {text}
      {showCursor && <Cursor frame={frame} size={36} />}
    </div>
  </div>
);

// ===========================================================================
// SCENE 1 — The prompt: "find me a list of fresh leads"
// ===========================================================================
const SCENE_1_DUR = 130;

const Scene1: React.FC = () => {
  const frame = useCurrentFrame();
  const { fps: vfps } = useVideoConfig();
  const termIn = springIn(frame, vfps, 2, "LIQUID");

  const promptText = typed(PROMPT, frame, 22, 32);
  const promptDone = promptText.length >= PROMPT.length;

  return (
    <AbsoluteFill style={{ padding: "5% 6%", fontFamily: MARKETING }}>
      <div style={{ width: "100%", height: "100%" }}>
        <TerminalChrome progress={termIn}>
          <div
            style={{
              display: "flex",
              flexDirection: "column",
              gap: 30,
              fontFamily: MONO,
            }}
          >
            {/* system line */}
            <div
              style={{
                fontSize: 26,
                color: COLORS.textSubtle,
                opacity: springIn(frame, vfps, 8, "GENTLE"),
              }}
            >
              claude-code v2.1 · connected to Apify MCP
            </div>

            {/* user prompt line */}
            <div style={{ marginTop: 20 }}>
              <PromptLine
                text={promptText}
                showCursor={!promptDone}
                frame={frame}
              />
            </div>
          </div>
        </TerminalChrome>
      </div>
    </AbsoluteFill>
  );
};

// ===========================================================================
// SCENE 2 — Claude answers + spins up sub-agents
// The terminal chrome is ALREADY present (progress = 1, no entrance) so the
// hard cut from Scene 1 reads as the SAME session continuing — only the new
// content (answer + agents) animates in.
// ===========================================================================
const SCENE_2_DUR = 150;

const SUBAGENTS = [
  { name: "agent-01", task: "crawl company directories" },
  { name: "agent-02", task: "extract contact records" },
  { name: "agent-03", task: "enrich with firmographics" },
  { name: "agent-04", task: "verify & dedupe" },
];

const AgentRow: React.FC<{
  agent: (typeof SUBAGENTS)[number];
  index: number;
}> = ({ agent, index }) => {
  const frame = useCurrentFrame();
  const { fps: vfps } = useVideoConfig();
  const p = staggeredSpring(frame, vfps, index, 40, 12, "ELASTIC");
  const tx = interpolate(p, [0, 1], [-40, 0]);
  const drift = ambientDrift(frame, 1.5, 90 + index * 12, `agent-${index}`);

  // spinner
  const spin = interpolate(frame, [40 + index * 12, 400], [0, 1440], {
    extrapolateRight: "clamp",
  });

  return (
    <div
      style={{
        display: "flex",
        alignItems: "center",
        gap: 24,
        padding: "22px 28px",
        backgroundColor: COLORS.card,
        border: `1px solid ${COLORS.border}`,
        borderRadius: 16,
        opacity: p,
        transform: `translateX(${tx}px) translateY(${drift}px)`,
      }}
    >
      {/* spinner ring */}
      <svg
        width={44}
        height={44}
        viewBox="0 0 44 44"
        style={{ transform: `rotate(${spin}deg)`, flexShrink: 0 }}
      >
        <circle
          cx="22"
          cy="22"
          r="17"
          fill="none"
          stroke={COLORS.border}
          strokeWidth="4"
        />
        <path
          d="M22 5 a17 17 0 0 1 17 17"
          fill="none"
          stroke={COLORS.orange}
          strokeWidth="4"
          strokeLinecap="round"
        />
      </svg>
      <div style={{ display: "flex", flexDirection: "column", gap: 6 }}>
        <div
          style={{
            fontFamily: MONO,
            fontSize: 30,
            color: COLORS.orange,
            fontWeight: 600,
          }}
        >
          {agent.name}
        </div>
        <div
          style={{
            fontFamily: MONO,
            fontSize: 26,
            color: COLORS.textMuted,
          }}
        >
          {agent.task}
        </div>
      </div>
    </div>
  );
};

const Scene2: React.FC = () => {
  const frame = useCurrentFrame();
  const { fps: vfps } = useVideoConfig();

  // Chrome is fully present from frame 0 — no re-entrance on the hard cut.
  const answerText = typed(ANSWER, frame, 8, 34);

  const labelIn = springIn(frame, vfps, 34, "GENTLE");

  return (
    <AbsoluteFill style={{ padding: "5% 6%", fontFamily: MARKETING }}>
      <div style={{ width: "100%", height: "100%" }}>
        <TerminalChrome progress={1}>
          <div
            style={{
              display: "flex",
              flexDirection: "column",
              gap: 28,
              height: "100%",
            }}
          >
            {/* carried-over prompt line — static, so the session feels continuous */}
            <PromptLine text={PROMPT} />

            {/* claude answer — types in */}
            <AnswerLine
              text={answerText}
              showCursor={answerText.length < ANSWER.length}
              frame={frame}
            />

            <div
              style={{
                fontFamily: MONO,
                fontSize: 24,
                color: COLORS.textSubtle,
                letterSpacing: "0.06em",
                opacity: labelIn,
                transform: `translateY(${interpolate(labelIn, [0, 1], [10, 0])}px)`,
              }}
            >
              ── SUB-AGENTS ──────────────────────────────
            </div>

            {/* agent grid */}
            <div
              style={{
                display: "grid",
                gridTemplateColumns: "1fr 1fr",
                gap: 22,
              }}
            >
              {SUBAGENTS.map((a, i) => (
                <AgentRow key={i} agent={a} index={i} />
              ))}
            </div>
          </div>
        </TerminalChrome>
      </div>
    </AbsoluteFill>
  );
};

// ===========================================================================
// SCENE 3 — Agents crawling the web (burning tokens)
// The terminal chrome is ALREADY present (progress = 1, no entrance) so the
// hard cut from Scene 2 reads as the SAME session continuing — the prompt +
// answer carry over statically, and only the new crawl log + token badge in.
// ===========================================================================
const SCENE_3_DUR = 150;

const CRAWL_LINES = [
  "GET  crunchbase.com/organizations",
  "GET  linkedin.com/company/…",
  "PARSE  contact records ✓ 214 found",
  "GET  apollo-directory/fintech",
  "ENRICH  firmographics ✓",
  "VERIFY  emails ✓ 198 valid",
];

const CrawlLine: React.FC<{ text: string; index: number }> = ({
  text,
  index,
}) => {
  const frame = useCurrentFrame();
  const { fps: vfps } = useVideoConfig();
  const p = staggeredSpring(frame, vfps, index, 20, 16, "GENTLE");
  const isOk = text.includes("✓");
  const drift = ambientDrift(frame, 1, 100 + index * 8, `crawl-${index}`);
  return (
    <div
      style={{
        display: "flex",
        gap: 20,
        fontFamily: MONO,
        fontSize: 30,
        opacity: p,
        transform: `translateY(${interpolate(p, [0, 1], [16, 0]) + drift}px)`,
        lineHeight: 1.4,
      }}
    >
      <span style={{ color: isOk ? COLORS.orange : COLORS.textSubtle }}>
        {isOk ? "✓" : "→"}
      </span>
      <span style={{ color: isOk ? COLORS.text : COLORS.textMuted }}>
        {text}
      </span>
    </div>
  );
};

const Scene3: React.FC = () => {
  const frame = useCurrentFrame();
  const { fps: vfps } = useVideoConfig();

  // token counter climbing — "burning frontier tokens"
  const tokenProg = interpolate(frame, [20, 120], [0, 1], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });
  const tokens = Math.round(interpolate(tokenProg, [0, 1], [0, 1_240_000]));

  const badgeIn = springIn(frame, vfps, 12, "SNAPPY");
  const badgePulse = 1 + Math.sin(frame / 8) * 0.02;

  const labelIn = springIn(frame, vfps, 6, "GENTLE");

  return (
    <AbsoluteFill style={{ padding: "5% 6%", fontFamily: MARKETING }}>
      <div style={{ width: "100%", height: "100%" }}>
        {/* Chrome fully present from frame 0 — no re-entrance on the hard cut. */}
        <TerminalChrome progress={1} title="claude — crawling">
          <div
            style={{
              display: "flex",
              flexDirection: "column",
              gap: 28,
              height: "100%",
            }}
          >
            {/* token burn badge — top right */}
            <div
              style={{
                position: "absolute",
                right: 48,
                top: -8,
                backgroundColor: COLORS.card,
                border: `2px solid ${COLORS.orange}`,
                borderRadius: 999,
                padding: "16px 34px",
                display: "flex",
                alignItems: "center",
                gap: 16,
                opacity: badgeIn,
                transform: `scale(${interpolate(
                  badgeIn,
                  [0, 1],
                  [0.85, 1],
                ) * badgePulse})`,
              }}
            >
              <span style={{ fontSize: 30 }}>🔥</span>
              <div
                style={{
                  fontFamily: MONO,
                  fontSize: 32,
                  color: COLORS.orange,
                  fontWeight: 600,
                  fontVariantNumeric: "tabular-nums",
                }}
              >
                {tokens.toLocaleString("en-US")} tokens
              </div>
            </div>

            {/* carried-over prompt + answer — static, so the session feels continuous */}
            <PromptLine text={PROMPT} />
            <AnswerLine text={ANSWER} />

            <div
              style={{
                fontFamily: MONO,
                fontSize: 24,
                color: COLORS.textSubtle,
                letterSpacing: "0.06em",
                maxWidth: "60%",
                opacity: labelIn,
                transform: `translateY(${interpolate(labelIn, [0, 1], [10, 0])}px)`,
              }}
            >
              agents reading pages…
            </div>

            <div
              style={{
                display: "flex",
                flexDirection: "column",
                gap: 18,
              }}
            >
              {CRAWL_LINES.map((l, i) => (
                <CrawlLine key={i} text={l} index={i} />
              ))}
            </div>
          </div>
        </TerminalChrome>
      </div>
    </AbsoluteFill>
  );
};

// ===========================================================================
// SCENE 4 — Cost comparison: Apify to Claude = ~1/3 the price
// (No headline, no chip, no CTA — the centered bars carry the story.)
// ===========================================================================
const SCENE_4_DUR = 140;

const CostBar: React.FC<{
  label: string;
  value: number; // relative width fraction 0-1
  cost: string;
  accent: boolean;
  delay: number;
  index: number;
}> = ({ label, value, cost, accent, delay, index }) => {
  const frame = useCurrentFrame();
  const { fps: vfps } = useVideoConfig();
  const p = spring({ frame, fps: vfps, delay, config: SPRINGS.LIQUID });
  const drift = ambientDrift(frame, 1, 110 + index * 20, `bar-${index}`);
  return (
    <div
      style={{
        display: "flex",
        flexDirection: "column",
        gap: 14,
        opacity: springIn(frame, vfps, delay - 4, "GENTLE"),
        transform: `translateY(${drift}px)`,
      }}
    >
      <div
        style={{
          display: "flex",
          justifyContent: "space-between",
          alignItems: "baseline",
        }}
      >
        <div
          style={{
            fontFamily: MONO,
            fontSize: 32,
            color: accent ? COLORS.text : COLORS.textMuted,
          }}
        >
          {label}
        </div>
        <div
          style={{
            fontFamily: MONO,
            fontSize: 46,
            fontWeight: 600,
            color: accent ? COLORS.orange : COLORS.textSubtle,
            fontVariantNumeric: "tabular-nums",
          }}
        >
          {cost}
        </div>
      </div>
      <div
        style={{
          height: 48,
          backgroundColor: COLORS.card,
          border: `1px solid ${COLORS.border}`,
          borderRadius: 24,
          overflow: "hidden",
        }}
      >
        <div
          style={{
            width: `${value * p * 100}%`,
            height: "100%",
            background: accent
              ? `linear-gradient(90deg, ${COLORS.orange}, ${COLORS.orangeDeep})`
              : COLORS.border,
            borderRadius: 24,
          }}
        />
      </div>
    </div>
  );
};

const Scene4: React.FC = () => {
  const frame = useCurrentFrame();
  const { fps: vfps } = useVideoConfig();

  const cardIn = springIn(frame, vfps, 6, "LIQUID");

  return (
    <AbsoluteFill
      style={{
        fontFamily: MARKETING,
        display: "flex",
        alignItems: "center",
        justifyContent: "center",
        padding: "6% 8%",
      }}
    >
      {/* comparison card — centered visual centerpiece */}
      <div
        style={{
          width: "64%",
          backgroundColor: COLORS.card,
          border: `1px solid ${COLORS.border}`,
          borderRadius: 32,
          padding: "56px 64px",
          display: "flex",
          flexDirection: "column",
          gap: 52,
          opacity: cardIn,
          transform: `translateY(${interpolate(cardIn, [0, 1], [46, 0])}px)`,
          boxShadow: "0 40px 100px rgba(0,0,0,0.5)",
        }}
      >
        <CostBar
          label="frontier tokens, raw"
          value={1}
          cost="$300"
          accent={false}
          delay={20}
          index={0}
        />
        <CostBar
          label="same job via Apify"
          value={0.34}
          cost="$100"
          accent
          delay={44}
          index={1}
        />
      </div>
    </AbsoluteFill>
  );
};

// ===========================================================================
// MAIN COMPOSITION
// ===========================================================================
export const durationInFrames =
  SCENE_1_DUR + SCENE_2_DUR + SCENE_3_DUR + SCENE_4_DUR - 3 * TRANSITION;

const MainComposition: React.FC = () => {
  const { fps: vfps, durationInFrames: total } = useVideoConfig();
  const camera = cameraDrift(useCurrentFrame(), total);

  return (
    <AbsoluteFill
      style={{ transform: camera.transform, transformOrigin: "50% 50%" }}
    >
      {/* The world — painted ONCE, behind every scene. */}
      <Background />

      <TransitionSeries>
        <TransitionSeries.Sequence durationInFrames={SCENE_1_DUR + TRANSITION}>
          <Scene1 />
        </TransitionSeries.Sequence>
        <TransitionSeries.Transition
          presentation={hardCut()}
          timing={linearTiming({ durationInFrames: TRANSITION })}
        />

        <TransitionSeries.Sequence durationInFrames={SCENE_2_DUR + TRANSITION}>
          <Scene2 />
        </TransitionSeries.Sequence>
        <TransitionSeries.Transition
          presentation={hardCut()}
          timing={linearTiming({ durationInFrames: TRANSITION })}
        />

        <TransitionSeries.Sequence durationInFrames={SCENE_3_DUR + TRANSITION}>
          <Scene3 />
        </TransitionSeries.Sequence>
        <TransitionSeries.Transition
          presentation={hardCut()}
          timing={linearTiming({ durationInFrames: TRANSITION })}
        />

        <TransitionSeries.Sequence durationInFrames={SCENE_4_DUR}>
          <Scene4 />
        </TransitionSeries.Sequence>
      </TransitionSeries>
    </AbsoluteFill>
  );
};

export default MainComposition;
